from PIL import Image, ImageDraw, ImageOps
im = Image.open('radiograph.jpg')
def gridcrop(name, x1,y1,x2,y2, s=4):
    c = im.crop((x1,y1,x2,y2)).convert('L')
    c = ImageOps.autocontrast(c, cutoff=1)
    c = c.resize(((x2-x1)*s, (y2-y1)*s), Image.LANCZOS)
    d = ImageDraw.Draw(c)
    for gx in range(x1, x2, 20):
        px=(gx-x1)*s; d.line([(px,0),(px,c.height)], fill=160, width=1)
        if gx%100==0: d.text((px+2,2), str(gx), fill=255)
    for gy in range(y1, y2, 20):
        py=(gy-y1)*s; d.line([(0,py),(c.width,py)], fill=160, width=1)
        if gy%100==0: d.text((2,py+2), str(gy), fill=255)
    c.save(f'crops/{name}.png')
gridcrop('LL_lowerant', 1000, 680, 1300, 940)
gridcrop('LL_3rdmolar2', 1720, 640, 2000, 920)
gridcrop('UR_premolar2', 900, 420, 1120, 620)
print("ok")
EOF", "description": "Fine-gridded crops of remaining suspect regions"}
